#include <stdio.h>

/* teste do desafio o-diario — counter_protocol (03-tdd 3.9.3).
   Canal retorno: nenhuma captura de stdout. Cada cenario zera o caderno
   (remove + um fopen "w" vazio) ANTES de chamar a funcao do aluno: assim
   o fopen de leitura nunca devolve NULL, e um aluno que nao grava nada
   reprova pelo sentinel em vez de derrubar o teste. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int oDiario(int dia);

SM_TEST(as_tres_linhas_do_dia_1) {
    FILE *semente = fopen("diario.txt", "w");
    fclose(semente);

    checa_int("o diario devolve 1", oDiario(1), 1,
              "com o caderno aberto, gravar as tres linhas da certo");

    FILE *f = fopen("diario.txt", "r");
    char linha[80] = "(nada gravado)";
    fgets(linha, 80, f);
    checa_str("a primeira linha do log", linha, "dia 1: acordei\n",
              "a primeira linha do diario traz o dia e o primeiro registro");
    fgets(linha, 80, f);
    checa_str("a segunda linha do log", linha, "dia 1: estudei C\n",
              "a segunda linha repete o dia e traz o segundo registro");
    fgets(linha, 80, f);
    checa_str("a terceira linha do log", linha, "dia 1: dormi\n",
              "a terceira linha fecha o dia");
    char fim[80] = "(nada gravado)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada gravado)",
              "o diario do dia acaba na terceira linha: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(o_dia_entra_pelo_formato) {
    FILE *semente = fopen("diario.txt", "w");
    fclose(semente);

    oDiario(7);

    FILE *f = fopen("diario.txt", "r");
    char linha[80] = "(nada gravado)";
    fgets(linha, 80, f);
    checa_str("a primeira linha do dia 7", linha, "dia 7: acordei\n",
              "o numero do dia vem do parametro, pelo %d do fprintf");
    fgets(linha, 80, f);
    checa_str("a segunda linha do dia 7", linha, "dia 7: estudei C\n",
              "o mesmo parametro preenche o buraco das tres linhas");
    fclose(f);
}

solutionCode:
#include <stdio.h>

int oDiario(int dia) {
    FILE *f = fopen("diario.txt", "w");
    if (f == NULL) {
        return 0;
    }
    fprintf(f, "dia %d: acordei\n", dia);
    fprintf(f, "dia %d: estudei C\n", dia);
    fprintf(f, "dia %d: dormi\n", dia);
    fclose(f);
    return 1;
}
